#pragma once
inline void testVulkanGoboUploadReadbackCandidate(HMODULE library,VkDevice device,VkPhysicalDevice physical,uint32_t family,VulkanMaterialImagesCandidate&images,const VtfRgbaImageCandidate&expected,size_t imageIndex=0,bool uploadImages=true){
 auto check=VulkanProjectedLightBufferCandidate::check;size_t bytes=expected.rgba.size(),padded=(bytes+111)/112*112;std::vector<uint8_t>zero(padded);
 VulkanProjectedLightBufferCandidate output(library,device);output.create(physical,zero.data(),zero.size(),VK_BUFFER_USAGE_TRANSFER_DST_BIT);
 VkCommandPool pool{};VkQueue queue{};bool submitted=false;load<PFN_vkGetDeviceQueue>(library,"vkGetDeviceQueue")(device,family,0,&queue);
 auto cleanup=[&]{if(submitted)load<PFN_vkQueueWaitIdle>(library,"vkQueueWaitIdle")(queue);if(pool)load<PFN_vkDestroyCommandPool>(library,"vkDestroyCommandPool")(device,pool,nullptr);};
 try{
  VkCommandPoolCreateInfo pi{};pi.sType=VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;pi.queueFamilyIndex=family;check(load<PFN_vkCreateCommandPool>(library,"vkCreateCommandPool")(device,&pi,nullptr,&pool));
  VkCommandBuffer command{};VkCommandBufferAllocateInfo ai{};ai.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;ai.commandPool=pool;ai.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY;ai.commandBufferCount=1;check(load<PFN_vkAllocateCommandBuffers>(library,"vkAllocateCommandBuffers")(device,&ai,&command));VkCommandBufferBeginInfo bi{};bi.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;check(load<PFN_vkBeginCommandBuffer>(library,"vkBeginCommandBuffer")(command,&bi));if(uploadImages)images.upload(command);
  VkImageMemoryBarrier barrier{};barrier.sType=VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;barrier.oldLayout=VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;barrier.newLayout=VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;barrier.srcAccessMask=VK_ACCESS_SHADER_READ_BIT;barrier.dstAccessMask=VK_ACCESS_TRANSFER_READ_BIT;barrier.srcQueueFamilyIndex=barrier.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;barrier.image=images.entries.at(imageIndex).image;barrier.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};load<PFN_vkCmdPipelineBarrier>(library,"vkCmdPipelineBarrier")(command,VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,0,0,nullptr,0,nullptr,1,&barrier);
  VkBufferImageCopy region{};region.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};region.imageExtent={expected.width,expected.height,1};load<PFN_vkCmdCopyImageToBuffer>(library,"vkCmdCopyImageToBuffer")(command,barrier.image,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,output.buffer,1,&region);
  barrier.oldLayout=VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;barrier.newLayout=VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;barrier.srcAccessMask=VK_ACCESS_TRANSFER_READ_BIT;barrier.dstAccessMask=VK_ACCESS_SHADER_READ_BIT;load<PFN_vkCmdPipelineBarrier>(library,"vkCmdPipelineBarrier")(command,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT,0,0,nullptr,0,nullptr,1,&barrier);
  VkMemoryBarrier host{};host.sType=VK_STRUCTURE_TYPE_MEMORY_BARRIER;host.srcAccessMask=VK_ACCESS_TRANSFER_WRITE_BIT;host.dstAccessMask=VK_ACCESS_HOST_READ_BIT;load<PFN_vkCmdPipelineBarrier>(library,"vkCmdPipelineBarrier")(command,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_HOST_BIT,0,1,&host,0,nullptr,0,nullptr);check(load<PFN_vkEndCommandBuffer>(library,"vkEndCommandBuffer")(command));VkSubmitInfo si{};si.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO;si.commandBufferCount=1;si.pCommandBuffers=&command;check(load<PFN_vkQueueSubmit>(library,"vkQueueSubmit")(queue,1,&si,VK_NULL_HANDLE));submitted=true;check(load<PFN_vkQueueWaitIdle>(library,"vkQueueWaitIdle")(queue));submitted=false;
  void*mapped=nullptr;check(load<PFN_vkMapMemory>(library,"vkMapMemory")(device,output.memory,0,padded,0,&mapped));bool equal=std::memcmp(mapped,expected.rgba.data(),bytes)==0;load<PFN_vkUnmapMemory>(library,"vkUnmapMemory")(device,output.memory);if(!equal)throw std::runtime_error("gobo image device copy mismatch");cleanup();std::cout<<"gobo_device_upload_readback=passed bytes="<<bytes<<" byte_exact=1 sampled_lighting=unverified\n";
 }catch(...){cleanup();throw;}
}
